\blem\label{lem-coh}
Let $X$ be a scheme and let $\sF$ and $\sG$ be coherent $\sO_X$\nobreakdash-mod\-ules.
\benumr
\item\label{ker-coker-coh} {If $\sF\To{f}\sG$ is a morphism of $\sO_X$\nobreakdash-mod\-ules, then $\Ker f$ and $\Coker f$ are coherent.}
\item\label{hom-tf} Assume that $X$ is integral. If $\sG$ is $\sO_X$-torsion-free, so is $\sHom_{\sO_X}(\sF,\sG)$. In~par\-ticular, $\sF^{\vee}$ is $\sO_X$-torsion-free.

Now, assume that $X$ is locally coherent.

\item\label{coh modules on coh rings} An $\sO_X$\nobreakdash-mod\-ule is coherent if and only if it is Zariski locally finitely presented.
\item\label{hom-coh} {$\sHom_{\sO_X}(\sF,\sG)$ is coherent. In particular, $\sF^{\vee}$ is coherent.}
\eenumr
\elem

\blem\label{lem-iso}
Let $R$ be {a} domain with topologically Noetherian spectrum and $\alpha\colon M\to N$ a morphism of $R$\nobreakdash-mod\-ules.
Then $\alpha$ is an isomorphism, provided that $N$ is torsion-free and every prime $\fp\subset R$ satisfies:
\begin{itemize}
\item
either $\alpha_{\fp}\colon M_{\fp}\to N_{\fp}$ is an isomorphism, or $\depth_{R_{\fp}}(M_{\fp})\geq 2$.
\end{itemize}
\elem

\bthm\label{Rflx-Pic-Vect on reg}
Let $X$ be a topologically locally Noetherian, integral, locally coherent, regular scheme.
For a closed subset $Z\subset X$ with $\wdim \sO_{X,z}\geq 2$ for all $z\in Z$ and the canonical open immersion $j\colon X\backslash Z\hra X$, the restriction $j^*$ and pushforward $j_*$ induce the following equivalences of categories:
\begin{equation*}\label{restriction}
\sO_{X}\text{-}\Rflx\isoto \sO_{X\backslash Z}\text{-}\Rflx,\qq \mathbf{Pic}\,X\isoto \mathbf{Pic}\, X\backslash Z.
\end{equation*}
In particular, for every scheme $Y$ affine over $X$, we have a bijection of sets
\[
\ts Y(X)\simeq Y(X\backslash Z).
\]
Moreover, if $\wdim\sO_{X,x}\leq 2$ for all $x\in X$, then we have an equivalence of categories:
\begin{equation*}
\mathbf{Vect}(X) \isoto \mathbf{Vect}(X\backslash Z).
\end{equation*}
\ethm

\bthm\label{normal-s2}
For a coherent domain $R$, the following are equivalent:
\benumr
\item\label{normal-s2-i} $R$ is normal;
\item \label{normal-s2-ii} $R$ is the intersection (in $\Frac R$) of its local rings which are valuation rings;
\item\label{normal-s2-iii} every local ring $A$ of $R$ is either a valuation ring, or for any $f\in \fm_A$ we have
\[
\fm_A\not\in \Ass(A/fA).
\]
\eenumr
\noindent
If local rings of $R$ have topologically Noetherian spectra, then these are equivalent~to
\begin{equation}
\x{every local ring of $R$ is either a valuation ring or of $\depth\geq 2.$} \label{S2} \tag{$\dagger$}
\end{equation}
\ethm

\bcl \label{cl-t}
We have $\fm_R=\fm_R^t$. In particular, every subideal $J\subset \fm_R$ satisfies $J^t\subset \fm_R$.
\ecl

\Subsection{Geometric properties and reduction methods}\blem\label{geom}
For a Prüfer domain $R$ with spectrum $S$, a finite type irreducible $S$-scheme $X$, a point $x\in X$ and its image $s\in S$, the following assertions hold
\benumr
\item\label{geo-i} all nonempty $S$-fibres have the same dimension;
\item\label{geo-iii} if $X$ is $S$-flat and $X_s$ is generically reduced, then for any maximal point $\xi\in X_s$, we have an extension of valuation rings
\[
\sO_{S,s}\hra \sO_{X,\xi}
\]
inducing an isomorphism of value groups;
\item\label{geo-iv} for $x\pr\in X$ with $x\pr \neq x$ whose image is denoted by $s\pr$, if $x\in \overline{\{x'\}}$, then
\begin{itemize}
\item {either $s=s'$}, and we have $\dim (\sO_{X_{s'},x'}) <\dim(\sO_{X_s,x})$;
\item or {$s\in \overline{\{s'\}}, s\neq s'$}, and we have $\dim (\sO_{X_{s'},x'}) \le \dim(\sO_{X_s,x})$.
\end{itemize}
\eenumr
\elem

\blem\label{enlarge valuation rings}
For a valuation ring $V$, an essentially finitely presented (resp essen\-tially smooth\footnote{By definition, this means that $A$ is a local ring of a smooth $V$-algebra.}) $V$-local algebra $A$, there are an extension of valuation rings $V'/V$ with trivial extension of value groups, and an essentially finitely presented (\resp essentially smooth) $V$-map $V'\to A$ with finite extension of residue fields.
\elem

\begin{thm-tweak} \label{Auslander's flatness criterion}
Let $V$ be a valuation ring, $X$ a $V$-smooth scheme, and $x\in X$ a point. Set $A\ce \sO_{X,x}$. Let $M$ be a reflexive $A$\nobreakdash-mod\-ule. If $\End_A(M)$ is isomorphic to a direct sum of copies of $M$, then $M$ is $A$-free.
\end{thm-tweak}

\begin{lemma-tweak} \label{the map l}
Let $V$ be a valuation ring that is not a field. Let $(V,\fm_V)\to (A, \mathfrak{m}_A)$ be an essentially smooth, local map of local rings. Denote by $A\x{-}\mathbf{Mod}_{\mathrm{tor, fp}}$ the collection of all finitely presented $A$\nobreakdash-mod\-ules $M$ supported on $\{\fm_A\}$. Then there exist a totally ordered abelian group $\Gamma$ and a map $l\colon A\x{-}\mathbf{Mod}_{\mathrm{tor, fp}}\to \GG_{\geq 0}$ satisfying the following properties:
\begin{itemize}
\item for $A$\nobreakdash-mod\-ule $M\in A\x{-}\mathbf{Mod}_{\mathrm{tor, fp}}$, we have $l(M)=0$ if and only if $M=0$;
\item for every acyclic, bounded complex $M^{\csbullet}$ such that $M^j\in A\x{-}\mathbf{Mod}_{\mathrm{tor, fp}}$ for each $j$, one has
\[
\ts \sum_j (-1)^j l(M^j)=0.
\]
\end{itemize}
\end{lemma-tweak}

\begin{lemma-tweak} \label{lem on isom of Ext's}
Let $(A,\fm_A)$ be a coherent local ring with a regular sequence of length $d\geq 1$. Let $M\To{\phi}N$ be a morphism of coherent $A$\nobreakdash-mod\-ules that induces an isomorphism over $\Spec A\backslash \{\fm_A\}$.
We have isomorphisms $\Ext_{A}^i(N,A)\To{\sim} \Ext_{A}^i(M,A)$ for all $i<d-1$ and a monomorphism $\Ext_{A}^{d-1}(N,A) \hto \Ext_{A}^{d-1}(M,A)$.
\end{lemma-tweak}

\begin{lemma-tweak}\label{coherence of Tor and Ext}
Let $V$ be a valuation ring, $X$ a $V$-smooth finite type scheme, and $x\in X$ a point that lies over a non-generic point $s\in \Spec V$. For finitely presented $A\ce \sO_{X,x}$\nobreakdash-mod\-ules $M$ and $N$, $\Ext_A^i(M,N)$ and $\Tor_i^A(M,N)$ are finitely presented over $A$ for all $i\ge 0$ and are zero for $i> d+1$, where $d=\dim \sO_{X_s,x}$.
\end{lemma-tweak}

\skpt\begin{defn-tweak} \label{def of torsos}
\begin{enumerate}
\item A (right) \emph{$G$-torsor} (for the fppf topology) is an $X$-algebraic space $\cP$ equipped with a $G$-action $a:\cP\times_X G \to \cP$ such that the following conditions hold:
\benumr\def\theenumii{\roman{enumii}}
\item the induced morphism $\cP\times_X G\to \cP \times_X \cP$, $(p,g)\mto (p,a(p,g))$, is an isomorphism; and
\item there exists a fppf covering $\{X_i\to X\}_{i\in I}$ of algebraic spaces \SP{03Y8} such that $\cP(X_i)\neq \emptyset$ for every $i\in I$.
\eenumr
\item For $G$-torsors $\cP_1$ and $\cP_2$, a \emph{morphism} $\cP_1 \to \cP_2$ is a $G$-equivariant morphism $\cP_1\to \cP_2$ of $X$-algebraic spaces.
\item By a trivialization of a $G$-torsor $\cP$ we mean a $G$-equivariant isomorphism $t:G \isoto \cP$, where $G$ acts on itself via right multiplication; this amounts to the choice of a section $t(1_G)\in \cP(X)$. A $G$-torsor $\cP$ is \emph{trivial} if there exists a trivialization, or, equivalently, if $\cP(X)\neq \emptyset$.
\end{enumerate}
\end{defn-tweak}

\blemt \label{lem on Isom}
For two $G$-torsors $\cP_1$ and $\cP_2$, $\un{\mathrm{Isom}}_X(\cP_1,\cP_2)$ is an algebraic space over~$S$. Further, $G\to X$ is quasi-compact (\resp étale, smooth, flat, separated, (local\-ly) of finite type, (locally) of finite presentation, quasi-affine, affine, or finite) if and only if $\un{\mathrm{Isom}}_X(\cP_1,\cP_2)\to X$ is so.
\elemt

\blemt [Descent $G$-torsors]\label{descent lem for torsors}
$\Psi$ is an equivalence of {categories}.
\elemt

\brem \label{rem on purity fo rel curves}
In higher relative dimensions, even in the classical Noetherian setting, the purity \Cref{purity for rel. dim 1} is inapplicable, even for the simplest group $G=\GL_{n}$. For instance, there exists a vector bundle over $\Spec(R)\backslash \{\mathfrak{m}_R\}$ that cannot be extended to $\Spec\, R$, where $(R,\mathfrak{m}_R)$ is any Noetherian regular local ring of Krull dimension at least three.
\erem

\bcor [Extending generically trivial torsors, {\cite[Cor.\,2.10]{GL23}}]\label{extend generically trivial torsors}
Fix
\benumr
\item $R$ a semilocal Prüfer domain with spectrum $S$;
\item $X$ an $S$-flat finite type quasi-separated scheme with regular fibres;
\item $Y$ the spectrum of a local ring of an affine open subset of $X$;
\item $r\in R$ a nonzero element; and
\item $G$ a reductive $X$-group scheme.
\eenumr
\noindent
Then, every generically trivial $G$-torsor over $Y$ (\resp over an open subset of $X[\sfrac{1}{r}]\ce X_{R[1/r]}$) extends to a $G$-torsor over an open subset $U\subset X$. Here, the complementary closed $Z\ce X\backslash U$ satisfies the condition:
\[
\begin{cases}
\codim(Z_{\eta}, X_{\eta})\geq 3 & \text{for each generic point $\eta\in S$,} \\
\codim(Z_s,X_s)\geq 2 & \text{for all $s\in S$.}
\end{cases}
\]
\ecor

\blem \label{geom paraf vs paraf}
Let $A$ be a local ring with a quasi-compact punctured spectrum. Then~ $A$ is geometrically parafactorial if and only if for any {local and essentially étale\footnote{Recall that by definition an essentially étale ring map is a localization of an étale ring map.}} map $A\to B$ of local rings, $B$ is parafactorial.
\elem

\brem
In the case when $X$ is a scheme, \Cref{lim-parafactorial}\eqref{lim-parafactorialii} implies that the first two assumptions above are equivalent to saying that the pair $(X,Z)$ is geometrically parafactorial in the sense of \Cref{geom-parafact}. Moreover, \Cref{geom parafact}\eqref{geom parafacti}--\eqref{geom parafactii} gives examples of such pairs $(X,Z)$, where $Z$ satisfies the conditions
\[
\begin{cases}
\codim(Z_{\eta}, X_{\eta})\geq 2 & \text{for every generic point $\eta\in S$,} \\
\codim(Z_s,X_s)\geq 1 & \text{for all $s\in S$.}
\end{cases}
\]

\erem

\bprop\label{local cohomology of tori}
In the Setup \ref{setup for purity over mult}, assume that $X$ is a scheme. For a point $z\in Z$ and an $\sO_{X,z}$-torus $T$, we have
\[
\text{$H^i_{\{z\},\fppf}(\Spec(\sO_{X,z}),T)\simeq H^i_{\{z\},\et}(\Spec(\sO_{X,z}),T)=0$ \q for \, $0\le i \le 2$. }
\]
\eprop

\bthm \label{purity for gp of mult type}
In the Setup \ref{setup for purity over mult},
we have
\begin{align*}
H^i_{\fppf}(X,M)&\isoto H^i_{\fppf}(X\backslash Z,M)\quad\text{for $i=0,1$, and}\\
H^2_{\fppf}(X,M)&\hra H^2_{\fppf}(X\backslash Z,M).
\end{align*}
\ethm

\blemt [{\cf \cite[Prop.\,4.1]{Ces22a}}] \label{geome. input}
For
\benumr
\item a semilocal Prüfer domain $R$;
\item a smooth, faithfully flat $R$-algebra $A$ of pure relative dimension $d\ge 1$;
\item a finite subset $\b{x}\subset X\ce \Spec\, A$;
\item a closed subscheme $Y\subset X$ that satisfies
\[
\begin{cases}
\codim(Y_s, X_s)\geq 1 & \text{for all closed points }s\in \Spec R, \text{ and} \\
\codim(Y_s,X_s)\geq 2 & \text{otherwise}.
\end{cases}
\]
\eenumr
\noindent
there are an affine open $U\subset \Spec\, A$ containing $\b{x}$, an affine open $S\subset \mathbb{A}_R^{d-1}$, and a smooth $R$-morphism $\pi:U\to S$ of relative dimension $1$ such that $Y\cap U$ is $S$-finite.
\elemt

\blemt [Lifting the torsor to a smooth relative curve; {\cf \cite[Prop.\,4.2]{Ces22a}}]\label{red q-s torsor to rel curve}
Let $R$ be a semilocal Prüfer domain with fraction field $K$.
Let $A$ be the semilocalization of an irreducible, $R$-smooth algebra $A'$ at a finite subset $\textbf{x}\subset \Spec A\pr$ and let~$G$ be a quasi-split reductive $A$-group scheme with a Borel subgroup $B$.
\begin{enumerate}
\item\label{red q-s torsor to rel curve1} Given a generically trivial $G$-torsor $P_K$ over $A_K\ce A\otimes_RK$, there are
\begin{enumerate}\def\theenumii{\roman{enumii}}
\item\label{red q-s torsor to rel curve1i} a smooth, affine relative $A$-curve $C$ with a section $s\in C(A)$;
\item\label{red q-s torsor to rel curve1ii} an $A$-finite closed subscheme $Z\subset C$;
\item\label{red q-s torsor to rel curve1iii} a quasi-split reductive $C$-group scheme $\sG$ with a Borel subgroup $\sB\subset \sG$ whose $s$-pullback is $B\subset G$, compatible with the quasi-pinnings;
\item\label{red q-s torsor to rel curve1iv} a $\sG$-torsor $\cP_K$ over $C_K\ce C\times_RK$ whose $s_{A_K}$-pullback is $P_K$ such that $\cP_K$ reduces to a {$\rad^u(\sB)$}-torsor over $C_K\backslash Z_K$ (here $s_{A_K}$ denotes the image of~$s$ in $C(A_K)$).
\end{enumerate}
\item\label{red q-s torsor to rel curve2} If $R$ has Krull dimension $1$ and $P$ is a generically trivial $G$-torsor, there are
\begin{enumerate}\def\theenumii{\roman{enumii}}
\item\label{red q-s torsor to rel curve2i} a smooth, affine relative $A$-curve $C$ with a section $s\in C(A)$;
\item\label{red q-s torsor to rel curve2ii} an $A$-finite closed subscheme $Z\subset C$;
\item\label{red q-s torsor to rel curve2iii} a quasi-split reductive $C$-group scheme $\sG$ with a Borel subgroup $\sB\subset \sG$ whose $s$-pullback is $B\subset G$, compatible with the quasi-pinnings;
\item\label{red q-s torsor to rel curve2iv} a $\sG$-torsor $\cP$ whose $s$-pullback is $P$ such that $\cP$ reduces to a {$\rad^u(\sB)$}-torsor over $C\backslash Z$.
\end{enumerate}
\end{enumerate}
\elemt

\blemt [Faithfully flat descent for coherent regularity] \label{ff descent coh reg}
For a faithfully flat ring map $A\to B$, if $B$ is coherent regular, then so is $A$.
\elemt

\blemt \label{a lem on linear algebra}
For a local ring $(A,\mathfrak{m}_A)$, a nonzero $A$\nobreakdash-mod\-ule $M$ supported on $\{\mathfrak{m}_A\}$, and a matrix $H\in \text{M}_{m\times n}(A)$, if the $A$-linear map $H_M:M^{\oplus n}\to M^{\oplus m}$ induced by $H$ (via left multiplication) is injective, then $H$ admits a left inverse, or, equivalently, $H$ exhibits $A^{\oplus n}$ as a direct summand of $A^{\oplus m}$.
\elemt
